public static SRSCatalogItemName getReportName()
{
    SRSCatalogItemName reportName = next getReportName();

    if (!SysCountryRegionCode::isLegalEntityInCountryRegion([#isoPL, #isoEE, #isoLT, #isoLV, #isoHU, #isoCZ]) && !BrazilParameters::isEnabled())
    {
        reportName = ssrsReportStr(AVACustTransOpenPerDate, Report);
    }

    return reportName;
}
